// #83bf5b מסך קבלת ההזמנה לוקח שם, חברה, מזמין ואימייל מפרמטרי הקישור — /accept берёт данные приглашения с сервера по token.
// Кейсы: .qa/tests/invitations/INV-05..INV-08 (INV-M1 — только вручную). План: specs/invitations.md, раздел 3.
// Две роли: ADMIN2 (компания B, .qa/auth/admin2.json) приглашает/отменяет, гость (без входа) открывает ссылку.
// НИКАКИХ РЕГИСТРАЦИЙ: запрос auth/v1/signup перехватывается (route.abort) и на сервер не уходит; проверяется только,
// какой email в нём. Адреса только qa-auto-inv-…@example.com; в конце каждого теста (finally) все приглашения
// qa-auto-inv-… отменяются через окно «ביטול ההזמנה». Тесты с приглашениями меняют данные компании B → @data.
// Факты QA 14–15.11.2026 (бандл после fdbef3f): ссылка в баннере — только ?token=; подменённые параметры не меняют экран;
// без token — «קישור ההזמנה אינו זמין» / «קישור ההזמנה חסר או שגוי.»; отменённый/случайный token — «ההזמנה אינה תקפה».
import { test, expect } from '../../fixtures';
import { Page } from '@playwright/test';
import { randomBytes } from 'crypto';
import { cancelAllInvites, cancelInviteConfirmed, invite as inviteUser, readBannerLink, rowOf } from '../helpers/invites';

const NAME = 'QA-AUTO Invite';
const COMPANY_B = 'QA Company B';
const SUBMIT = 'קבע סיסמה והיכנס';
const INVALID_TITLE = 'ההזמנה אינה תקפה';
const INVALID_TEXT = 'ההזמנה בוטלה או שאינה תקפה עוד. פנו למנהל החשבון.';
const MISSING_TITLE = 'קישור ההזמנה אינו זמין';
const MISSING_TEXT = 'קישור ההזמנה חסר או שגוי.';
const SIGNUP = '**/auth/v1/signup**';
const QA_PATTERN = /qa-auto-inv-/;

const run = () => `${Date.now()}-${Math.floor(Math.random() * 1000)}`;
const qaEmail = () => `qa-auto-inv-${run()}@example.com`;

/** Подменённые параметры ссылки (все — заведомо чужие значения QA-AUTO). */
function spoofParams() {
  return {
    email: `qa-auto-inv-spoof-${run()}@example.com`,
    name: 'QA-AUTO Spoof',
    company: 'QA-AUTO Other Co',
    inviter: 'QA-AUTO Inviter',
  };
}
type Spoof = ReturnType<typeof spoofParams>;

/** Ссылка + подменённые email/name/company/inviter (token не трогаем). */
function withSpoof(link: string, s: Spoof) {
  const url = new URL(link);
  for (const [k, v] of Object.entries(s)) url.searchParams.set(k, v);
  return url.toString();
}

const emailField = (guest: Page) => guest.getByRole('textbox', { name: /אימייל/ });
const passwordField = (guest: Page) => guest.getByLabel(/סיסמה חדשה/);
const inviterLine = (guest: Page) => guest.getByText(/צירף אותך/);

/** Гость: считать запросы signUp на странице (без перехвата). */
function watchSignup(guest: Page): string[] {
  const calls: string[] = [];
  guest.on('request', (r) => {
    if (r.url().includes('/auth/v1/signup')) calls.push(r.url());
  });
  return calls;
}

/** Ни одно подменённое значение не показано на странице. */
async function expectNoSpoof(guest: Page, s: Spoof) {
  for (const v of [s.name, s.company, s.inviter, s.email]) {
    await expect(guest.getByText(v), `подменённое значение «${v}» на экране`).toHaveCount(0);
  }
}

/** Форма принятия с данными приглашения (только смотрим). */
async function expectInviteForm(guest: Page, email: string) {
  await expect(guest.getByText(new RegExp(`שלום ${NAME}.*הוזמנת לחשבון של`))).toBeVisible();
  await expect(guest.getByText(COMPANY_B, { exact: true })).toBeVisible();
  await expect(inviterLine(guest)).toBeVisible();
  await expect(emailField(guest)).toHaveValue(email);
  await expect(emailField(guest)).not.toBeEditable();
  await expect(passwordField(guest)).toBeVisible();
  await expect(guest.getByRole('button', { name: SUBMIT })).toBeVisible();
  await expect(guest.getByText(INVALID_TITLE)).toHaveCount(0);
}

async function expectNoForm(guest: Page) {
  await expect(passwordField(guest)).toHaveCount(0);
  await expect(guest.getByRole('button', { name: SUBMIT })).toHaveCount(0);
}

async function expectInvalid(guest: Page) {
  await expect(guest.getByRole('heading', { name: INVALID_TITLE })).toBeVisible();
  await expect(guest.getByText(INVALID_TEXT, { exact: true })).toBeVisible();
  await expect(guest.getByText('חזרה לכניסה', { exact: true })).toBeVisible();
  await expectNoForm(guest);
}

/** Очистка: отменить (с подтверждением) все приглашения qa-auto-inv-…; строк qa-auto-inv- не осталось. */
async function cleanup(admin: Page) {
  await cancelAllInvites(admin, QA_PATTERN);
  await expect(admin.getByRole('row').filter({ hasText: QA_PATTERN })).toHaveCount(0);
}

test.describe('מסך קבלת ההזמנה — נתונים מהשרת לפי token', () => {
  test('קישור ההזמנה בבאנר מכיל רק token #83bf5b @desktop @data', async ({ asUser }) => {
    const admin = await asUser('admin2');
    const email = qaEmail();
    try {
      await inviteUser(admin, NAME, email);
      const link = await readBannerLink(admin);
      const url = new URL(link);
      expect(url.pathname, 'путь ссылки').toBe('/accept');
      expect(url.searchParams.get('token'), 'token').toMatch(/^[0-9a-f]{32,}$/i);
      expect([...url.searchParams.keys()], 'в ссылке только token, без email/name/company/inviter').toEqual(['token']);
      for (const v of [email, encodeURIComponent(email), 'QA-AUTO', 'Company']) {
        expect(link, `в ссылке нет «${v}»`).not.toContain(v);
      }
    } finally {
      await cleanup(admin);
    }
  });

  test('טוקן תקף עם email/name/company/inviter מזויפים — המסך מציג את נתוני ההזמנה, האימייל נעול #83bf5b @desktop @data', async ({ asUser }) => {
    const admin = await asUser('admin2');
    const guest = await asUser('guest');
    const email = qaEmail();
    const spoof = spoofParams();
    try {
      await inviteUser(admin, NAME, email);
      const link = await readBannerLink(admin);

      // Контроль: настоящая ссылка — данные приглашения; запоминаем строку пригласившего (с сервера).
      await guest.goto(link);
      await expectInviteForm(guest, email);
      const inviterReal = (await inviterLine(guest).textContent())?.trim();
      expect(inviterReal, 'строка «<пригласивший> צירף אותך»').toBeTruthy();

      // Подмена в той же ссылке (token тот же).
      const signups = watchSignup(guest);
      await guest.goto(withSpoof(link, spoof));
      await expectInviteForm(guest, email);
      await expect(inviterLine(guest)).toHaveText(inviterReal!);
      await expectNoSpoof(guest, spoof);
      expect(signups, 'открытие ссылки не вызывает signUp').toEqual([]);
    } finally {
      await cleanup(admin);
    }
  });

  test('טוקן תקף עם email מזויף — בשליחה signUp יוצא עם אימייל ההזמנה (הבקשה נחסמת) #83bf5b @desktop @data', async ({ asUser }) => {
    const admin = await asUser('admin2');
    const guest = await asUser('guest');
    const email = qaEmail();
    const spoof = spoofParams();
    try {
      await inviteUser(admin, NAME, email);
      const link = await readBannerLink(admin);

      // Регистрации нет: каждый signUp прерывается до сервера, запоминаем только email из тела запроса.
      const sent: string[] = [];
      await guest.route(SIGNUP, (route) => {
        const body = JSON.parse(route.request().postData() ?? '{}') as { email?: string };
        sent.push(String(body.email ?? ''));
        return route.abort('blockedbyclient');
      });

      await guest.goto(withSpoof(link, spoof));
      await expectInviteForm(guest, email);
      await passwordField(guest).fill(`QaAuto${randomBytes(4).toString('hex')}9`);
      const signup = guest.waitForRequest((r) => r.url().includes('/auth/v1/signup'));
      await guest.getByRole('button', { name: SUBMIT }).click();
      await signup;

      expect(sent.length, 'ровно один запрос signUp').toBe(1);
      expect(sent[0], 'email в signUp — из приглашения, не из ссылки').toBe(email);
      expect(sent[0]).not.toBe(spoof.email);
    } finally {
      await guest.unrouteAll({ behavior: 'ignoreErrors' });
      await cleanup(admin);
    }
  });

  test('הזמנה שבוטלה + פרמטרים מזויפים — "ההזמנה אינה תקפה", בלי טופס #83bf5b @desktop @data', async ({ asUser }) => {
    const admin = await asUser('admin2');
    const guest = await asUser('guest');
    const email = qaEmail();
    const spoof = spoofParams();
    try {
      await inviteUser(admin, NAME, email);
      const link = await readBannerLink(admin);
      await cancelInviteConfirmed(admin, email);
      await expect(rowOf(admin, email)).toHaveCount(0);

      const signups = watchSignup(guest);
      await guest.goto(withSpoof(link, spoof));
      await expectInvalid(guest);
      await expectNoSpoof(guest, spoof);
      expect(signups).toEqual([]);
    } finally {
      await cleanup(admin);
    }
  });
});

test.describe('מסך קבלת ההזמנה — בלי token / token אקראי (אורח)', () => {
  const spoofQuery = (s: Spoof) => new URLSearchParams(s).toString();
  const cases = [
    { label: 'בלי token', url: () => '/accept', missing: true },
    { label: 'בלי token, רק פרמטרים מזויפים', url: (s: Spoof) => `/accept?${spoofQuery(s)}`, missing: true },
    {
      label: 'token אקראי עם פרמטרים מזויפים',
      url: (s: Spoof) => `/accept?token=${randomBytes(32).toString('hex')}&${spoofQuery(s)}`,
      missing: false,
    },
  ];
  for (const c of cases) {
    const title = c.missing ? MISSING_TITLE : INVALID_TITLE;
    test(`${c.label} — "${title}", בלי טופס #83bf5b @desktop @prod-safe`, async ({ asUser }) => {
      const guest = await asUser('guest');
      const spoof = spoofParams();
      const signups = watchSignup(guest);
      await guest.goto(c.url(spoof));
      if (c.missing) {
        await expect(guest.getByRole('heading', { name: MISSING_TITLE })).toBeVisible();
        await expect(guest.getByText(MISSING_TEXT, { exact: true })).toBeVisible();
        await expectNoForm(guest);
      } else {
        await expectInvalid(guest);
      }
      await expectNoSpoof(guest, spoof);
      expect(signups).toEqual([]);
    });
  }
});
